<span class="line"><span style="color:#C678DD;">    const</span><span style="color:#C678DD;"> struct</span><span style="color:#ABB2BF;"> file_operations </span><span style="color:#C678DD;">*</span><span style="color:#ABB2BF;">f_op;</span><span style="color:#7F848E;font-style:italic;"> // 操作函数表</span></span>
